(() => {
'use strict';
const $=id=>document.getElementById(id),core=()=>window.DashboardCore,c=()=>window.Community,client=()=>c()?.client,user=()=>c()?.user;
const s={pop:new Map(),popKey:'',popAt:0,popRequest:0,popBusy:false,popError:'',epoch:0,request:0,uid:null,notifications:[],unread:0,page:0,more:false,loading:false};
const line=(tag,value,cls='')=>{const n=document.createElement(tag);n.textContent=value;n.className=cls;return n};
const button=(label,run,cls='')=>{const b=line('button',label,cls);b.type='button';b.onclick=run;return b};
const error=e=>/fetch|network/i.test(e?.message||'')?'연결하지 못했습니다. 잠시 후 다시 시도해 주세요.':e?.message||'불러오지 못했습니다. 잠시 후 다시 시도해 주세요.';
const votes=id=>Number(s.pop.get(id)?.votes||0);
function renderPopular(){if(!core())return;const rows=core().filteredResources().filter(r=>votes(r.id)>0).sort((a,b)=>votes(b.id)-votes(a.id)||(s.pop.get(b.id)?.last_liked||'').localeCompare(s.pop.get(a.id)?.last_liked||'')||a.id.localeCompare(b.id)).slice(0,5),list=$('popular-list');list.replaceChildren();for(const [i,row]of rows.entries()){const item=line('article','','popular-item'),rank=line('b',String(i+1).padStart(2,'0'),'popular-rank'),body=line('div','','popular-body'),a=line('a',row.title);try{a.href=core().validURL(row.url)}catch{continue}a.target='_blank';a.rel='noopener';body.append(a,line('small',row.source+' · 최근 7일 유용해요 '+votes(row.id)));item.append(rank,body,button('댓글 보기',()=>c().openThread(row)));list.append(item)}if(!rows.length)$('popular-note').textContent=s.popError|| (s.popBusy?'인기 자료를 확인하고 있습니다.':client()?'아직 이 조건의 자료에 최근 7일간 받은 유용해요가 없습니다.':'커뮤니티를 연결하면 인기 자료가 표시됩니다.');else $('popular-note').textContent='유용해요를 취소하면 순위에도 반영됩니다.';$('popular-resources').classList.toggle('active',core().state.sort==='popular')}
async function refreshPopularity(force=false){if(!client()||!core())return;const ids=core().effectiveResources().map(r=>r.id).sort(),key=ids.join(',');if(!force&&(s.popBusy||key===s.popKey&&Date.now()-s.popAt<60000))return;const request=++s.popRequest;s.popBusy=true;s.popError='';s.popKey=key;s.popAt=Date.now();renderPopular();try{const chunks=[];for(let i=0;i<ids.length;i+=100)chunks.push(ids.slice(i,i+100));const parts=await Promise.all(chunks.map(async ids=>{const r=await client().rpc('defi_popular_resources',{p_ids:ids});if(r.error)throw r.error;return r.data||[]}));if(request!==s.popRequest)return;s.pop=new Map(parts.flat().map(row=>[row.resource_id,row]));s.popBusy=false;core().render()}catch(e){if(request===s.popRequest){s.popBusy=false;s.popError=$('popular-note').textContent='인기 자료를 불러오지 못했습니다. ↻ 버튼으로 다시 시도해 주세요.'}}}
function afterRender(){renderPopular();Promise.resolve().then(()=>refreshPopularity())}
function invalidatePopularity(){s.popAt=0;refreshPopularity(true)}
function renderBadge(){const b=$('notifications-badge');b.hidden=!user()||!s.unread;b.textContent=s.unread>99?'99+':String(s.unread);$('notifications-open').setAttribute('aria-label',user()&&s.unread?'안 읽은 알림 '+s.unread+'개':'알림');$('notifications-read-all').disabled=!user()||s.unread===0}
function resetAccount(){s.epoch++;s.request++;s.uid=null;s.notifications=[];s.unread=0;s.page=0;s.more=false;s.loading=false;$('notifications-badge').hidden=true;$('notifications-list').replaceChildren();$('notifications-error').textContent='';$('notifications-dialog').close();renderBadge()}
async function authChanged(){resetAccount();s.uid=user()?.id||null;await refreshNotifications(true,true)}
async function refreshNotifications(reset=true,quiet=false){if(quiet&&s.loading)return;const uid=user()?.id;if(!uid||!client()){renderBadge();return}const epoch=s.epoch,request=++s.request;if(!quiet)s.loading=true;try{const count=await client().from('defi_notifications').select('id',{count:'exact',head:true}).eq('recipient_id',uid).is('read_at',null);if(count.error)throw count.error;if(epoch!==s.epoch||request!==s.request||uid!==user()?.id)return;s.unread=count.count||0;renderBadge();if(quiet||!$('notifications-dialog').open)return;const page=reset?0:s.page,r=await client().from('defi_notifications').select('id,recipient_id,resource_id,comment_id,kind,read_at,created_at,actor:defi_profiles!defi_notifications_actor_id_fkey(display_name),comment:defi_comments!defi_notifications_comment_id_fkey(body,parent_id)').eq('recipient_id',uid).order('created_at',{ascending:false}).order('id',{ascending:false}).range(page*30,page*30+29);if(r.error)throw r.error;if(epoch!==s.epoch||request!==s.request||uid!==user()?.id)return;s.notifications=[...new Map((reset?(r.data||[]):[...s.notifications,...(r.data||[])]).map(n=>[n.id,n])).values()];s.page=page+1;s.more=(r.data||[]).length===30;$('notifications-error').textContent='';renderNotifications()}catch(e){if(epoch===s.epoch&&!quiet)$('notifications-error').textContent=error(e)}finally{if(request===s.request)s.loading=false}}
function renderNotifications(){const list=$('notifications-list');list.replaceChildren();if(!s.notifications.length)list.append(line('p','아직 받은 알림이 없습니다.','notification-empty'));for(const n of s.notifications){const row=line('article','','notification-row'+(!n.read_at?' is-unread':'')),open=button('',()=>openNotification(n),'notification-item');open.append(line('b',(n.actor?.display_name||'이용자')+(n.kind==='reply'?'님이 내 댓글에 답글을 남겼어요.':'님이 내 자료에 댓글을 남겼어요.')),line('p',String(n.comment?.body||'댓글을 확인하세요.').slice(0,150)),line('small',new Date(n.created_at).toLocaleString('ko-KR')+(n.read_at?' · 읽음':' · 안 읽음')));row.append(open);list.append(row)}$('notifications-more').hidden=!s.more}
async function markRead(n){if(!user()||n.read_at)return;const uid=user().id,epoch=s.epoch,r=await client().from('defi_notifications').update({read_at:new Date().toISOString()}).eq('id',n.id).eq('recipient_id',uid).select('id');if(r.error)throw r.error;if(epoch!==s.epoch)return;n.read_at=new Date().toISOString();await refreshNotifications(true,true);renderNotifications()}
async function openNotification(n){const uid=user()?.id,epoch=s.epoch;if(!uid)return;try{await markRead(n);let row=core().effectiveResources().find(r=>r.id===n.resource_id)||(window.Member?.archivedResources||[]).find(r=>r.id===n.resource_id)||c().resources.find(r=>r.id===n.resource_id);if(!row){const r=await client().from('defi_resources').select('*,defi_profiles(display_name)').eq('id',n.resource_id).maybeSingle();if(r.error)throw r.error;if(r.data)row={...r.data,community:true,contributor:r.data.defi_profiles?.display_name||'이용자'}}if(epoch!==s.epoch||uid!==user()?.id)return;if(!row||window.Member?.applyControl(row).hidden){$('notifications-error').textContent='이 자료는 현재 목록에 없거나 삭제·숨김 처리되었습니다.';return}$('notifications-dialog').close();await c().openThread(row,n.comment_id)}catch(e){if(epoch===s.epoch)$('notifications-error').textContent=error(e)}}
async function markAll(){if(!user())return;const uid=user().id,epoch=s.epoch;$('notifications-read-all').disabled=true;try{const r=await client().from('defi_notifications').update({read_at:new Date().toISOString()}).eq('recipient_id',uid).is('read_at',null);if(r.error)throw r.error;if(epoch!==s.epoch)return;await refreshNotifications(true)}catch(e){if(epoch===s.epoch)$('notifications-error').textContent=error(e)}finally{renderBadge()}}
async function refresh(){await Promise.all([refreshPopularity(true),refreshNotifications(true)])}
$('popular-refresh').onclick=()=>refreshPopularity(true);$('popular-resources').onclick=()=>{const state=core().state;Object.assign(state,{council:'all',category:'all',region:'all',search:'',savedOnly:false,interestsOnly:false,sort:'popular',limit:20});$('resource-search').value='';$('resource-sort').value='popular';core().navigate('resources');core().render();refreshPopularity(true)};
$('notifications-open').onclick=async()=>{if(!user()){c().openAuth();return}$('notifications-error').textContent='';$('notifications-dialog').showModal();$('notifications-list').replaceChildren(line('p','알림을 불러오는 중입니다.','note'));await refreshNotifications(true)};$('notifications-close').onclick=()=>$('notifications-dialog').close();$('notifications-refresh').onclick=()=>refreshNotifications(true);$('notifications-more').onclick=()=>refreshNotifications(false);$('notifications-read-all').onclick=markAll;
setInterval(()=>{if(user()&&document.visibilityState!=='hidden')refreshNotifications(true,true)},30000);window.addEventListener('focus',()=>{if(user())refreshNotifications(true,true)});
window.Social={votes,afterRender,refreshPopularity,invalidatePopularity,refreshNotifications,resetAccount,authChanged,refresh};
renderBadge();if(client())authChanged();
})();
